import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

// Animation item interface
interface AnimationItem {
  id: string;
  type: 'text' | 'list' | 'component';
  priority: number;
  dependencies: string[];
  status: 'pending' | 'active' | 'completed';
  onStart: () => void;
  onComplete: () => void;
}

// Animation context interface
interface AnimationContextType {
  registerAnimation: (
    type: AnimationItem['type'],
    options: {
      priority?: number;
      dependencies?: string[];
      onStart?: () => void;
      onComplete?: () => void;
    }
  ) => string;
  completeAnimation: (id: string) => void;
  isAnimating: boolean;
  currentAnimation: AnimationItem | null;
  pauseAll: () => void;
  resumeAll: () => void;
  resetQueue: () => void;
}

// Create the context with default values
const AnimationContext = createContext<AnimationContextType>({
  registerAnimation: () => '',
  completeAnimation: () => {},
  isAnimating: false,
  currentAnimation: null,
  pauseAll: () => {},
  resumeAll: () => {},
  resetQueue: () => {},
});

// Custom hook to use the animation context
export const useAnimation = () => useContext(AnimationContext);

// Animation provider props
interface AnimationProviderProps {
  children: ReactNode;
  routeKey?: string; // Used to reset queue on route changes
}

// Generate unique ID for animations
let nextId = 1;
const generateId = (type: string) => `${type}-${nextId++}`;

export const AnimationProvider: React.FC<AnimationProviderProps> = ({ 
  children,
  routeKey
}) => {
  // Queue of animations to process
  const [queue, setQueue] = useState<AnimationItem[]>([]);

  // Currently active animation
  const [currentAnimation, setCurrentAnimation] = useState<AnimationItem | null>(null);

  // Paused state
  const [isPaused, setIsPaused] = useState(false);

  // Reset queue when route changes
  useEffect(() => {
    if (routeKey) {
      resetQueue();
    }
  }, [routeKey]);

  // Process next animation in queue when current one completes
  useEffect(() => {
    if (isPaused || currentAnimation) {
      return;
    }

    // Add a small delay to avoid React batching issues
    const timer = setTimeout(() => {
      const processQueue = () => {
        // No items in queue
        if (queue.length === 0) {
          return;
        }

        // Find next eligible animation (no pending dependencies)
        const next = queue.find(item => {
          if (item.status !== 'pending') {
            return false;
          }

          // Check if all dependencies are completed
          return item.dependencies.every(depId => 
            !queue.some(qItem => qItem.id === depId && qItem.status !== 'completed')
          );
        });

        if (next) {
          // Update item status
          setQueue(prevQueue => 
            prevQueue.map(item => 
              item.id === next.id ? { ...item, status: 'active' } : item
            )
          );

          // Set as current animation
          setCurrentAnimation(next);

          // Call onStart callback
          next.onStart();
        }
      };

      // Process next item
      processQueue();
    }, 10);

    return () => clearTimeout(timer);
  }, [queue, currentAnimation, isPaused]);

  // Register a new animation
  const registerAnimation = (
    type: AnimationItem['type'],
    options: {
      priority?: number;
      dependencies?: string[];
      onStart?: () => void;
      onComplete?: () => void;
    } = {}
  ): string => {
    const id = generateId(type);

    const newItem: AnimationItem = {
      id,
      type,
      priority: options.priority || 0,
      dependencies: options.dependencies || [],
      status: 'pending',
      onStart: options.onStart || (() => {}),
      onComplete: options.onComplete || (() => {}),
    };

    // Add to queue, sorted by priority
    setQueue(prevQueue => 
      [...prevQueue, newItem].sort((a, b) => b.priority - a.priority)
    );

    return id;
  };

  // Mark an animation as complete
  const completeAnimation = (id: string) => {
    // Find the animation in the queue
    const animation = queue.find(item => item.id === id);

    if (animation) {
      // Call onComplete callback
      animation.onComplete();

      // Update queue status
      setQueue(prevQueue => 
        prevQueue.map(item => 
          item.id === id ? { ...item, status: 'completed' } : item
        )
      );

      // Only clear current animation if it matches
      if (currentAnimation?.id === id) {
        setCurrentAnimation(null);
      }
    }
  };

  // Pause all animations
  const pauseAll = () => {
    setIsPaused(true);
  };

  // Resume animations
  const resumeAll = () => {
    setIsPaused(false);
  };

  // Reset the queue
  const resetQueue = () => {
    setQueue([]);
    setCurrentAnimation(null);
    setIsPaused(false);
    nextId = 1; // Reset ID counter
  };

  // Animation context value
  const contextValue: AnimationContextType = {
    registerAnimation,
    completeAnimation,
    isAnimating: !!currentAnimation,
    currentAnimation,
    pauseAll,
    resumeAll,
    resetQueue,
  };

  return (
    <AnimationContext.Provider value={contextValue}>
      {children}
    </AnimationContext.Provider>
  );
};
